        } else if (num < secondMinNegativeNum) {
            secondMinNegativeNum = num;
        } else if (num > maxPositiveNum) {
            secondMaxPositiveNum = maxPositiveNum;
            maxPositiveNum = num;
        } else if (num > secondMaxPositiveNum) {
