var numSubseq = function(nums, target) {
    nums.sort((a, b) => a - b);
    var res = 0;
    var l = 0;
    var r = nums.length - 1;
    var mod = Math.pow(10, 9) + 7;
    var pows = Array(nums.length);
    pows[0] = 1;
    for (var i = 1; i < nums.length; i++) {
