    }
    while (l <= r) {
        if (nums[l] + nums[r] <= target) {
            res += pows[r - l];
            res %= mod;
            l++;
        } else {
            r--;
        }
    }
    return res;
};

/**
 * @param {number[]} arr
 * @return {boolean}
 */
var canMakeArithmeticProgression = function(arr) {
    if (arr.length <= 2) return true;
    arr.sort((a, b) => a - b);
    const differ = arr[1] - arr[0];
    return arr.every((item, i) => i === 0 || item - arr[i - 1] === differ);
};

/**
 * @param {number} n
 * @param {number[]} left
 * @param {number[]} right 
 * @return {number}
 */
var getLastMoment = function(n, left, right) {
    var max = 0;
    for (var i = 0; i < left.length; i++) {
        max = Math.max(max, left[i]);
    }
    for (var j = 0; j < right.length; j++) {
        max = Math.max(max, n - right[j]);
    }
    return max;
};

/**
 * @param {number[]} nums
 * @param {number} n
 * @param {number} left
 * @param {number} right
 * @return {number}
 */
var rangeSum = function(nums, n, left, right) {
    var queue = new MinPriorityQueue();
    for (var i = 0; i < nums.length; i++) {
        queue.enqueue(i, nums[i]);
    }
    var res = 0;
    var mod = Math.pow(10, 9) + 7;
    for (var j = 0; j < right; j++) {
        var { element, priority } = queue.dequeue();
        if (element < nums.length - 1) {
            queue.enqueue(element + 1, priority + nums[element + 1]);
        }
        if (j >= left - 1) {
            res += priority;
            res %= mod;
        }
    }
    return res;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minDifference = function(nums) {
    if (nums.length <= 4) return 0;
    nums.sort((a, b) => a - b);
    return Math.min(
        nums[nums.length - 4] - nums[0],
        nums[nums.length - 3] - nums[1],
        nums[nums.length - 2] - nums[2],
        nums[nums.length - 1] - nums[3],
    );
};

/**
 * @param {number[]} nums
