    for (var i = 0; i < nums.length; i++) {
        map[nums[i] - 1]++;
    }
    var res = 0;
    for (var j = 0; j < map.length; j++) {
        res += helper(map[j] - 1);
    }
    return res;
};

var helper = function(num) {
    return num * (1 + num) / 2;
};

/**
 * @param {string} s
 * @param {number} k
 * @return {number}
 */
var getLengthOfOptimalCompression = function(s, k) {
    var cache = {};
    var helper = function(i, k, prev, prevCount) {
        if (k < 0) return Number.MAX_SAFE_INTEGER;
        if (i === s.length - k) return 0;

        var cacheKey = `${i}-${k}-${prev}-${prevCount}`;
        if (cache[cacheKey] !== undefined) return cache[cacheKey];

        var res = 0;
        if (s[i] === prev) {
            // keep
            var diff = [1, 9, 99].includes(prevCount) ? 1 : 0;
            res = diff + helper(i + 1, k, prev, prevCount + 1);
        } else {
            res = Math.min(
                // delete
                helper(i + 1, k - 1, prev, prevCount),
                // keep
                1 + helper(i + 1, k, s[i], 1),
            );
        }
        cache[cacheKey] = res;
        return res;
    };
    return helper(0, k, '', 0);
};

/**
 * @param {number[]} arr
 * @param {number} k
 * @return {number}
 */
var getWinner = function(arr, k) {
    var maxIndex = 0;
    for (var i = 1; i < arr.length; i++) {
        if (arr[i] > arr[maxIndex]) maxIndex = i;
        if (i - maxIndex + (maxIndex === 0 ? 0 : 1) === k) break;
    }
    return arr[maxIndex];
};

/**
