            && s[i] !== res[res.length - 1]
            && s[i].toLowerCase() === res[res.length - 1].toLowerCase()
        ) {
            res.pop();
        } else {
            res.push(s[i]);
        }
        i += 1;
    }
    return res.join('');
};

/**
