/**
 * @param {number[][]} mat
 * @return {number}
 */
var diagonalSum = function(mat) {
    var res = 0;
    for (var i = 0; i < mat.length; i++) {
        res += mat[i][i] + mat[i][mat.length - 1 - i];
    }
    if (mat.length % 2) {
        var mid = Math.floor(mat.length / 2);
        res -= mat[mid][mid];
    }
    return res;
};

/**
 * @param {string} colors
