 */
var minCost = function(colors, neededTime) {
    var cost = 0;
    var sum = 0;
    var max = 0;
    var color = '';
    for (var i = 0; i < colors.length; i++) {
        if (color === colors[i]) {
            sum += neededTime[i];
            max = Math.max(max, neededTime[i]);
        } else {
            color = colors[i];
            cost += (sum - max);
            sum = neededTime[i];
            max = neededTime[i];
        }
    }
    cost += (sum - max);
    return cost;
};

/**
