var numSpecial = function(mat) {
    var res = 0;
    for (var i = 0; i < mat.length; i++) {
        var specialCol = -1;
        var hasOnlyOne = false;
        for (var j = 0; j < mat[i].length; j++) {
            if (mat[i][j] === 1) {
                if (specialCol === -1) {
                    specialCol = j;
                    hasOnlyOne = true;
                } else {
                    hasOnlyOne = false;
                }
            }
        }
        if (!hasOnlyOne) continue;
        var isValid = true;
        for (var k = 0; k < mat.length; k++) {
            if (mat[k][specialCol] === 1 && k !== i) {
                isValid = false;
                break;
            }
        }
        if (isValid) res += 1;
    }
    return res;
};

/**
 * @param {number} n
 * @param {number[][]} preferences
 * @param {number[][]} pairs
 * @return {number}
 */
var unhappyFriends = function(n, preferences, pairs) {
    var preferenceMap = Array(n).fill(0).map(() => Array(n));
    for (var i = 0; i < preferences.length; i++) {
        for (var j = 0; j < preferences[i].length; j++) {
            preferenceMap[i][preferences[i][j]] = j;
        }
    }
    var pairMap = Array(n);
    for (var m = 0; m < pairs.length; m++) {
        pairMap[pairs[m][0]] = pairs[m][1];
        pairMap[pairs[m][1]] = pairs[m][0];
    }
    var res = 0;
    for (var k = 0; k < n; k++) {
        judge(preferenceMap, pairMap, k, n) && res++;
    }
    return res;
};

var judge = function(preferenceMap, pairMap, i, n) {
    for (var k = 0; k < n; k++) {
        if (k === i || k === pairMap[i]) continue;
        if (preferenceMap[i][pairMap[i]] > preferenceMap[i][k]
            && preferenceMap[k][pairMap[k]] > preferenceMap[k][i]) {
            return true;
        }
    }
    return false;
};

/**
 * @param {number[][]} points
 * @return {number}
 */
var minCostConnectPoints = function(points) {
    var edges = [];
    for (var i = 0; i < points.length; i++) {
        for (var j = i + 1; j < points.length; j++) {
            edges.push([i, j, getDistance(points, i, j)]);
        }
    }
    edges.sort((a, b) => a[2] - b[2]);
    var res = 0;
    var parents = Array(points.length).fill(0).map((_, i) => i);
    var rank = Array(points.length).fill(0);
    for (var m = 0; m < edges.length; m++) {
        var [i, j, distance] = edges[m];
        var n = find(parents, i);
        var k = find(parents, j);
        if (n === k) continue;
        if (rank[n] <= rank[k]) {
            union(parents, n, k);
            rank[k]++;
        } else {
            union(parents, k, n);
            rank[n]++;
        }
        res += distance;
    }
    return res;
};

var getDistance = function(points, i, j) {
    return Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
};

var union = function(parents, i, j) {
    parents[i] = j;
};

var find = function(parents, i) {
    if (parents[i] === i) {
        return i;
    }
    parents[i] = find(parents, parents[i]);
    return parents[i];
};

/**
 * @param {number} n
 * @param {number[][]} requests
 * @return {number}
 */
var maximumRequests = function(n, requests) {
    return solve(n,  requests, Array(n).fill(0), 0, 0);
};

var solve = function(n, requests, indegree, index, count) {
    // end
    if (index === requests.length) {
        return indegree.every(i => i === 0) ? count : 0;
    }
    // take this request
    indegree[requests[index][0]]--;
    indegree[requests[index][1]]++;
    const res = solve(n, requests, indegree, index + 1, count + 1);
    indegree[requests[index][0]]++;
    indegree[requests[index][1]]--;
    // ignore this request
    return Math.max(
        res,
        solve(n, requests, indegree, index + 1, count),
    );
};

/**
 * @param {number[]} rowSum
 * @param {number[]} colSum
 * @return {number[][]}
 */
var restoreMatrix = function(rowSum, colSum) {
    var m = rowSum.length;
    var n = colSum.length;
    var res = Array(m).fill(0).map(() => Array(n).fill(0));
    for (var i = 0; i < m; i++) {
        res[i][0] = rowSum[i];
    }
    for (var i = 0; i < n - 1; i++) {
        for (var j = 0; j < m; j++) {
            var num = Math.min(res[j][i], colSum[i]);
            res[j][i + 1] = res[j][i] - num;
            res[j][i] = num;
            colSum[i] -= num;
        }
    }
    return res;
};

/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @return {boolean}
 */
var isEvenOddTree = function(root) {
    var nodesOfLevel = [root];
    var level = 0;
    while (nodesOfLevel.length) {
        var newNodesOfLevel = [];
        for (var i = 0; i < nodesOfLevel.length; i++) {
            if (level % 2) {
                if (nodesOfLevel[i].val % 2) return false;
                if (i > 0 && nodesOfLevel[i].val >= nodesOfLevel[i - 1].val) return false;
            } else {
                if (nodesOfLevel[i].val % 2 === 0) return false;
                if (i > 0 && nodesOfLevel[i].val <= nodesOfLevel[i - 1].val) return false;
            }
            nodesOfLevel[i].left && newNodesOfLevel.push(nodesOfLevel[i].left);
            nodesOfLevel[i].right && newNodesOfLevel.push(nodesOfLevel[i].right);
        }
        nodesOfLevel = newNodesOfLevel;
        level += 1;
    }
    return true;
};

/**
 * @param {number} n
 * @param {number[][]} roads
 * @return {number}
 */
var maximalNetworkRank = function(n, roads) {
    var map = {};
    for (var i = 0; i < roads.length; i++) {
        var [m, k] = roads[i];
        if (!map[m]) map[m] = {};
        if (!map[k]) map[k] = {};
        map[m][k] = true;
        map[k][m] = true;
    }
    var res = 0;
    for (var i = 0; i < n; i++) {
        for (var j = i + 1; j < n; j++) {
            res = Math.max(
                res,
                Object.keys(map[i] || {}).length
                    + Object.keys(map[j] || {}).length
                    - (map[i] && map[i][j] ? 1 : 0)
            );
        }
    }
    return res;
};

/**
 * @param {string} s
 * @return {number}
 */
var maxLengthBetweenEqualCharacters = function(s) {
    var leftPosMap = Array(26);
    var rightPosMap = Array(26);
    var a = 'a'.charCodeAt(0);
    for (var i = 0; i < s.length; i++) {
        var j = s[i].charCodeAt(0) - a;
        if (leftPosMap[j] === undefined) leftPosMap[j] = i;
        rightPosMap[j] = i;
    }
    var max = -1;
    for (var m = 0; m < 26; m++) {
        if (leftPosMap[m] !== rightPosMap[m]) {
            max = Math.max(max, rightPosMap[m] - leftPosMap[m] - 1);
        }
    }
    return max;
};

/**
 * @param {number[]} nums
 * @param {number[]} l
 * @param {number[]} r
 * @return {boolean[]}
 */
var checkArithmeticSubarrays = function(nums, l, r) {
    return l.map((_, i) => check(nums, l[i], r[i]));
};

var check = function(nums, l, r) {
    var map = {};
    var min = Number.MAX_SAFE_INTEGER;
    var max = Number.MIN_SAFE_INTEGER;
    for (var i = l; i <= r; i++) {
        min = Math.min(min, nums[i]);
        max = Math.max(max, nums[i]);
        map[nums[i]] = true;
    }
    var diff = (max - min) / (r - l);
    for (var num = min; num < max; num += diff) {
        if (map[num] === undefined) {
            return false;
        }
    }
    return true;
};

/**
 * @param {number[][]} points
 * @return {number}
 */
var maxWidthOfVerticalArea = function(points) {
    var maxGap = 0;
    points.sort((a, b) => a[0] - b[0]);
    for (var i = 1; i < points.length; i++) {
        maxGap = Math.max(maxGap, points[i][0] - points[i - 1][0]);
    }
    return maxGap;
};

/**
 * @param {number[]} heights
 * @param {number} bricks
 * @param {number} ladders
 * @return {number}
 */
var furthestBuilding = function(heights, bricks, ladders) {
    var queue = new MinPriorityQueue();
    for (var i = 0; i < heights.length - 1; i++) {
        if (heights[i + 1] <= heights[i]) continue;
        queue.enqueue(heights[i + 1] - heights[i], heights[i + 1] - heights[i]);
        if (queue.size() > ladders) {
            var height = queue.dequeue().element;
            if (bricks < height) return i;
            bricks -= height;
        }
    }
    return heights.length - 1;
};

/**
 * @param {string} s
 * @return {number}
 */
var minDeletions = function(s) {
    var frequencyMap = {};
    for (var i = 0; i < s.length; i++) {
        frequencyMap[s[i]] = (frequencyMap[s[i]] || 0) + 1;
    }
    var frequencies = Object.values(frequencyMap).sort((a, b) => b - a);
    var duplicatedFrequencies = [];
    var result = 0;
    for (var j = 0; j < frequencies.length; j++) {
        var frequency = frequencies[j];
        if (frequency === frequencies[j + 1]) {
            duplicatedFrequencies.push(frequency);
            continue;
        }
        while (duplicatedFrequencies.length && frequency > (frequencies[j + 1] || 0) + 1) {
            frequency -= 1;
            result += duplicatedFrequencies.pop() - frequency;
        }
    }
    while (duplicatedFrequencies.length) {
        result += duplicatedFrequencies.pop();
    }
    return result;
};

/**
 * @param {string} s
 * @return {number}
 */
var minimumDeletions = function(s) {
  var map = Array(s.length).fill(0);
  for (var i = s.length - 2; i >= 0; i--) {
    map[i] = map[i + 1] + (s[i + 1] === 'a' ? 1 : 0);
  }
  return solve(s, 0, 0, Array(s.length), map);
};

var solve = function(s, i, num, map, map2) {
    if (i >= s.length) return 0;
    if (map[i] === undefined) {
      if (s[i] === 'a') {
        map[i] = solve(s, i + 1, 0, map, map2);
      } else {
        map[i] = Math.min(
          solve(s, i + 1, 1, map, map2),
          map2[i],
        );
      }
    }
    return map[i] + num;
};

/**
 * @param {number[]} nums
 * @param {number} x
 * @return {number}
 */
var minOperations = function(nums, x) {
    var leftSumMap = { 0: 0 };
    var rightSumMap = { 0: 0 };
    var leftSum = 0;
    var rightSum = 0;
    var min = Number.MAX_SAFE_INTEGER;
    for (var i = 0; i < nums.length; i++) {
      leftSum += nums[i];
      rightSum += nums[nums.length - 1 - i];
      leftSumMap[leftSum] = i + 1;
      rightSumMap[rightSum] = i + 1;
      if (rightSumMap[x - leftSum] !== undefined && (i + 1 + rightSumMap[x - leftSum]) <= nums.length) {
        min = Math.min(min, i + 1 + rightSumMap[x - leftSum]);
      }
      if (leftSumMap[x - rightSum] !== undefined && (i + 1 + leftSumMap[x - rightSum]) <= nums.length) {
        min = Math.min(min, i + 1 + leftSumMap[x - rightSum]);
      }
    }
    return min === Number.MAX_SAFE_INTEGER ? -1 : min;
};

/**
 * @param {string[]} word1
 * @param {string[]} word2
 * @return {boolean}
 */
var arrayStringsAreEqual = function(word1, word2) {
    var i = 0;
    var m = 0;
    var j = 0;
    var n = 0;
    while (i < word1.length && j < word2.length) {
        if (word1[i][m] !== word2[j][n]) return false;
        if (m === word1[i].length - 1) {
            i += 1;
            m = 0;
        } else {
            m += 1;
        }
        if (n === word2[j].length - 1) {
            j += 1;
            n = 0;
        } else {
            n += 1;
        }
    }
    return i === word1.length && j === word2.length;
};

/**
 * @param {number[]} nums
 * @return {number[]}
 */
var getSumAbsoluteDifferences = function(nums) {
    var diffLeft = Array(nums.length);
    for (var i = 0; i < nums.length; i++) {
        if (i === 0) {
            diffLeft[i] = 0;
        } else {
            diffLeft[i] = diffLeft[i - 1] + (nums[i] - nums[i - 1]) * i;
        }
    }
    var diffRight = Array(nums.length);
    for (var j = nums.length - 1; j >= 0; j--) {
        if (j === nums.length - 1) {
            diffRight[j] = 0;
        } else {
            diffRight[j] = diffRight[j + 1] + (nums[j + 1] - nums[j]) * (nums.length - 1 - j);
        }
    }
    var diff = Array(nums.length);
    for (var k = 0; k < nums.length; k++) {
        diff[k] = diffLeft[k] + diffRight[k];
    }
    return diff;
};

/**
 * @param {number} n
 * @return {number}
 */
var numberOfMatches = function(n) {
    if (n === 1) return 0;
    if (n % 2) {
        return Math.floor(n / 2) + numberOfMatches((n + 1) / 2);
    } else {
        return (n / 2) + numberOfMatches(n / 2);
    }
};

/**
 * @param {number[]} students
 * @param {number[]} sandwiches
 * @return {number}
 */
var countStudents = function(students, sandwiches) {
    var numOfOnes = 0;
    var numOfZeros = 0;
    for (var i = 0; i < students.length; i++) {
        if (students[i] === 1) numOfOnes++;
        else numOfZeros++;
    }
    for (var j = 0; j < sandwiches.length; j++) {
        if (sandwiches[j] === 1) {
            if (numOfOnes > 0) numOfOnes--;
            else break;
        } else {
            if (numOfZeros > 0) numOfZeros--;
            else break;
        }
    }
    return numOfOnes + numOfZeros;
};

/**
 * @param {string} s
 * @return {boolean}
 */
var halvesAreAlike = function(s) {
    var map = {
        a: true,
        e: true,
        i: true,
        o: true,
        u: true,
        A: true,
        E: true,
        I: true,
        O: true,
        U: true,
    };
    var half = s.length / 2;
    var count = 0;
    for (var i = 0; i < half; i++) {
        if (map[s[i]]) count++;
        if (map[s[i + half]]) count--;
    }
    return count === 0;
};

/**
 * @param {number} n
 * @return {number}
 */
var totalMoney = function(n) {
    var weeks = Math.floor(n / 7);
    var lastWeekDays = n % 7;
    var sumOfWeeks = (4 + 4 + weeks - 1) * 7 * weeks / 2;
    var sumOfLastDays = Array(lastWeekDays).fill(0).reduce((sum, _, i) => {
        return sum + (i + 1) + weeks;
    }, 0);
    return sumOfWeeks + sumOfLastDays;
};

/**
 * @param {string} s
 * @param {number} x
 * @param {number} y
 * @return {number}
 */
var maximumGain = function(s, x, y) {
    var stack = [];
    var score = 0;
    var a = x > y ? 'ab' : 'ba';
    var b = x > y ? 'ba' : 'ab';
    var ax = x > y ? x : y;
    var bx = x > y ? y : x;
    var score = 0;
    for (var i = 0; i < s.length; i++) {
        if (stack[stack.length - 1] === a[0] && s[i] === a[1]) {
            stack.pop();
            score += ax;
        } else {
            stack.push(s[i]);
        }
    }
    s = stack.join('');
    stack = [];
    for (var i = 0; i < s.length; i++) {
