    var emptyChairs = new Set();
    var max = -1;
    var list = times.reduce((arr, item, i) => {
        arr.push({ i, type: 1, time: item[0] });
        arr.push({ i, type: 2, time: item[1] });
        return arr;
    }, []).sort((a, b) => {
        // be careful if someone's arrival time equals the other's leave time
        // make sure we process leave one first
        if (a.time === b.time) {
            return b.type - a.type;
        }
        return a.time - b.time;
    });
    var map = {};
    for (var i = 0; i < list.length; i++) {
        var item = list[i];
        if (item.type === 1) {
            // someone arrival
            if (emptyChairs.size) {
                // found empty chair someone left before
                map[item.i] = findMin(emptyChairs);
                emptyChairs.delete(map[item.i]);
            } else {
                // go to the last chair
                map[item.i] = max + 1;
                max = map[item.i];
            }
            if (item.i === targetFriend) {
                break;
            }
        } else {
            // someone leave
            emptyChairs.add(map[item.i]);
        }
    }
    return map[targetFriend];
};

// should replace set with min heap
// so that time complexity could be O(nlog(n))
var findMin = function(list) {
    return Array.from(list).sort((a, b) => a - b)[0];
};

/**
 * @param {number[]} obstacles
 * @return {number[]}
 */
var longestObstacleCourseAtEachPosition = function(obstacles) {
    var res = Array(obstacles.length).fill(1);
    var stack = [];
    for (var i = 0; i < obstacles.length; i++) {
        if (!stack.length || obstacles[i] >= stack[stack.length - 1]) {
            res[i] = (stack.length || 0) + 1;
            stack.push(obstacles[i]);
        } else {
            var index = binarySearch(stack, obstacles[i]);
            res[i] = index + 1;
            stack[index] = obstacles[i];
        }
    }
    return res;
};

var binarySearch = function(arr, num) {
    var left = 0;
    var right = arr.length - 1;
    while (left < right) {
        var mid = left + Math.floor((right - left) / 2);
        if (arr[mid] <= num) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
};

/**
 * @param {number} row
 * @param {number} col
 * @param {number[][]} cells
 * @return {number}
 */
var latestDayToCross = function(row, col, cells) {
    var left = 0;
    var right = cells.length - 1;
    while (left < right) {
        var mid = left + Math.ceil((right - left) / 2);
        if (canCross(row, col, cells, mid)) {
            left = mid;
        } else {
            right = mid - 1;
        }
    }
    return left + 1;
};

var canCross = function(row, col, cells, day) {
    var grid = Array(row).fill(0).map(() => Array(col).fill(0));
    for (var i = 0; i <= day; i++) {
        grid[cells[i][0] - 1][cells[i][1] - 1] = 1;
    }
    var queue = [];
    for (var i = 0; i < col; i++) {
        if (grid[0][i] === 0) {
            queue.push([0, i]);
            grid[0][i] = 2;
        }
    }
    while (queue.length !== 0) {
        var [r, c] = queue.shift();
        if (r === row - 1) return true;
        if (grid[r - 1] && grid[r - 1][c] === 0) {
            queue.push([r - 1, c]);
            grid[r - 1][c] = 2;
        }
        if (grid[r + 1] && grid[r + 1][c] === 0) {
            queue.push([r + 1, c]);
            grid[r + 1][c] = 2;
        }
        if (grid[r][c - 1] === 0) {
            queue.push([r, c - 1]);
            grid[r][c - 1] = 2;
        }
        if (grid[r][c + 1] === 0) {
            queue.push([r, c + 1]);
            grid[r][c + 1] = 2;
        }
    }
    return false;
};

/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number} source
 * @param {number} destination
 * @return {boolean}
 */
var validPath = function(n, edges, source, destination) {
    var dp = Array(n);
    var map = Array(n).fill(0).map(() => []);
    for (var i = 0; i < edges.length; i++) {
        map[edges[i][0]].push(edges[i][1]);
        map[edges[i][1]].push(edges[i][0]);
    }
    var dfs = function(i) {
        if (i === destination) return true;
        if (dp[i] !== undefined) return dp[i];
        dp[i] = false;
        for (var j = 0; j < map[i].length; j++) {
            if (dfs(map[i][j])) {
                dp[i] = true;
                break;
            }
        }
        return dp[i];
    };
    return dfs(source);
};

/**
 * @param {string[]} nums
 * @return {string}
 */
var findDifferentBinaryString = function(nums) {
    var str = '';
    for (var i = 0; i <= nums.length; i++) {
        str = i.toString(2);
        str = '0'.repeat(nums.length - str.length) + str;
        if (!nums.includes(str)) {
            return str;
        }
    }
};

/**
 * @param {string} word
 * @param {character} ch
 * @return {string}
 */
var reversePrefix = function(word, ch) {
    var index = word.indexOf(ch);
    if (index === -1) return word;
    var arr = word.split('');
    for (var i = 0; i < index / 2; i++) {
        var tmp = arr[i];
        arr[i] = arr[index - i];
        arr[index - i] = tmp;
    }
    return arr.join('');
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minOperations = function(nums) {
    nums.sort((a, b) => a - b);

    var uniqueNums = [];
    for (var i = 0; i < nums.length; i++) {
        if (nums[i] !== nums[i - 1]) uniqueNums.push(nums[i]);
    }

    var left = 0;
    var maxUniqueNumsInRange = 0;
    for (var right = 0; right < uniqueNums.length; right++) {
        while (uniqueNums[right] - uniqueNums[left] >= nums.length) left++;
        maxUniqueNumsInRange = Math.max(maxUniqueNumsInRange, right - left + 1);
    }

    return nums.length - maxUniqueNumsInRange;
};

/**
 * @param {string} answerKey
 * @param {number} k
 * @return {number}
 */
var maxConsecutiveAnswers = function(answerKey, k) {
    var max = 1;
    var numF = answerKey[0] === 'F' ? 1 : 0;
    var numT = answerKey[0] === 'T' ? 1 : 0;
    var left = 0;
    var right = 0;
    while (left <= right && right <= answerKey.length - 1) {
        if (Math.min(numF, numT) <= k) {
            max = Math.max(max, right - left + 1);
            right += 1;
            answerKey[right] === 'T' ? numT++ : numF++;
        } else {
            answerKey[left] === 'T' ? numT-- : numF--;
            left += 1;
        }
    }
    return max;
};

/**
 * @param {string} colors
 * @return {boolean}
 */
var winnerOfGame = function(colors) {
    var i = 0;
    var a = 0;
    var b = 0;
    while (i < colors.length) {
        var j = i;
        while (colors[j] === colors[i]) j++;
        if (j - i >= 3) {
            if (colors[i] === 'A') {
                a += j - i - 2;
            } else {
                b += j - i - 2;
            }
        }
        i = j;
    }
    return a > b;
};

/**
 * @param {number} n
 * @param {number[][]} relations
 * @param {number[]} time
 * @return {number}
 */
var minimumTime = function(n, relations, time) {
    var graph = Array(n).fill(0).map(() => []);
    for (var i = 0; i < relations.length; i++) {
        var [a, b] = relations[i];
        graph[a - 1].push(b - 1);
    }

    var max = 0;
    var dp = Array(n);
    for (var i = 0; i < n; i++) {
        max = Math.max(max, dfs(i, graph, time, dp));
    }
    return max;
};

var dfs = function(i, graph, time, dp) {
    if (dp[i] !== undefined) return dp[i];
    var max = 0;
    for (var j = 0; j < graph[i].length; j++) {
        max = Math.max(max, dfs(graph[i][j], graph, time, dp));
    }
    dp[i] = max + time[i];
    return dp[i];
};

/**
 * @param {string[]} arr
 * @param {number} k
 * @return {string}
 */
var kthDistinct = function(arr, k) {
    var map = {};
    for (var i = 0; i < arr.length; i++) {
        map[arr[i]] = (map[arr[i]] || 0) + 1;
    }
    for (var j = 0; j < arr.length; j++) {
        if (map[arr[j]] === 1) {
            k--;
            if (k === 0) return arr[j];
        }
    }
    return '';
};

/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {number[]}
 */
var nodesBetweenCriticalPoints = function(head) {
    var firstPoint = -1;
    var lastPoint = -1;
    var last = null;
    var now = head;
    var i = 0;
    var minDistance = Number.MAX_SAFE_INTEGER;
    while (now) {
        if (last && now.next && ((now.val > last.val && now.val > now.next.val) || (now.val < last.val && now.val < now.next.val))) {
            if (firstPoint === -1) firstPoint = i;
            if (lastPoint !== -1) minDistance = Math.min(minDistance, i - lastPoint);
            lastPoint = i;
        }
        last = now;
        now = now.next;
        i += 1;
    }
    if (firstPoint !== -1 && lastPoint !== -1 && lastPoint !== firstPoint) {
        return [minDistance, lastPoint - firstPoint];
    }
    return [-1, -1];
};

/**
 * @param {number} n
 * @param {number[][]} meetings
 * @param {number} firstPerson
 * @return {number[]}
 */
var findAllPeople = function(n, meetings, firstPerson) {
    var map = Array(n).fill(0).map(() => []);
    var queue = new MinPriorityQueue();
    var hasSecretMap = Array(n);
    var handledMap = Array(meetings.length);
    hasSecretMap[0] = true;
    hasSecretMap[firstPerson] = true;
    for (var i = 0; i < meetings.length; i++) {
        map[meetings[i][0]].push([meetings[i][1], meetings[i][2], i]);
        map[meetings[i][1]].push([meetings[i][0], meetings[i][2], i]);
        queue.enqueue(
            [...meetings[i], i],
            (hasSecretMap[meetings[i][0]] || hasSecretMap[meetings[i][1]])
                ? meetings[i][2] - 0.1
                : meetings[i][2]
        );
    }
    while (queue.size() !== 0) {
        var item = queue.dequeue().element;
        if (handledMap[item[3]]) continue;
        handledMap[item[3]] = true;
        if (!hasSecretMap[item[0]] && !hasSecretMap[item[1]]) continue;
        if (hasSecretMap[item[0]] && hasSecretMap[item[1]]) continue;
        var num = hasSecretMap[item[0]] ? item[1] : item[0];
        for (var i = 0; i < map[num].length; i++) {
            var data = map[num][i];
            if (handledMap[data[2]]) continue;
            if (hasSecretMap[data[0]]) continue;
            queue.enqueue(
                [num, data[0], data[1] - 0.1, data[2]],
                data[1] - 0.1
            );
        }
        hasSecretMap[num] = true;
    }
    return hasSecretMap.reduce((res, item, i) => {
        if (item) res.push(i);
        return res;
    }, []);
};

/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @param {number} startValue
 * @param {number} destValue
 * @return {string}
 */
var getDirections = function(root, startValue, destValue) {
    var findLCA = function(node) {
        if (!node) return false;
        if (node.val === startValue || node.val === destValue) {
            return node;
        }
        var left = findLCA(node.left);
        var right = findLCA(node.right);
        return (left && right) ? node : (left || right || false);
    };
    var findStart = function(node) {
        if (!node) return null;
        if (node.val === startValue) return '';

        var left = findStart(node.left);
        if (left !== null) return left + 'U';

        var right = findStart(node.right);
        if (right !== null) return right + 'U';

        return null;
    };
    var findDest = function(node) {
        if (!node) return null;
        if (node.val === destValue) return '';

        var left = findDest(node.left);
        if (left !== null) return 'L' + left;

        var right = findDest(node.right);
        if (right !== null) return 'R' + right;

        return null;
    };
    var LCA = findLCA(root);
    var startPath = findStart(LCA);
    var destPath = findDest(LCA);
    return startPath + destPath;
};

/**
 * @param {string} s
 * @return {boolean}
 */
var checkString = function(s) {
    var hasB = false;
    for (var i = 0; i < s.length; i++) {
        if (s[i] === 'a' && hasB) return false;
        hasB = s[i] === 'b';
    }
    return true;
};

/**
 * @param {string[]} bank
 * @return {number}
 */
var numberOfBeams = function(bank) {
    var res = 0;
    var lastRowDeviceNum = 0;
    for (var i = 0; i < bank.length; i++) {
        var deviceNum = 0;
        for (var j = 0; j < bank[i].length; j++) {
            if (bank[i][j] === '1') deviceNum++;
        }
        if (deviceNum === 0) continue;
        res += lastRowDeviceNum * deviceNum;
        lastRowDeviceNum = deviceNum;
    }
    return res;
};

/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {number}
 */
var pairSum = function(head) {
    var num = 0;
    var node = head;
    while (node) {
        num++;
        node = node.next;
    }

    var stack = [];
    var sum = 0;
    var i = 0;
    while (i < num) {
        if (i < num / 2) {
            stack.push(head.val);
        } else {
            sum = Math.max(sum, head.val + stack.pop());
        }
        i += 1;
        head = head.next;
    }

    return sum;
};

/**
 * @param {number[][]} questions
 * @return {number}
 */
var mostPoints = function(questions) {
    var dp = Array(questions.length);
    for (var i = questions.length - 1; i >= 0; i--) {
        var [points, brainpower] = questions[i];
        dp[i] = Math.max(
            points + (dp[i + brainpower + 1] || 0),
            dp[i + 1] || 0,
        );
    }
    return dp[0];
};

/**
 * @param {string} corridor
 * @return {number}
 */
var numberOfWays = function(corridor) {
    var num = BigInt(1);
    var mod = BigInt(Math.pow(10, 9) + 7);
    var seatNum = 0;
    var plantNum = 0;
    for (var i = 0; i < corridor.length; i++) {
        if (corridor[i] === 'S') {
            if (seatNum === 2) {
                num *= BigInt(plantNum + 1);
                num %= mod;
                seatNum = 1;
                plantNum = 0;
            } else {
                seatNum += 1;
            }
        } else {
            if (seatNum === 2) {
                plantNum += 1;
            }
        }
    }
    return seatNum === 2 ? Number(num) : 0;
};

/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var mergeNodes = function(head) {
    var newHead = new ListNode();
    var resNow = newHead;
    var now = head;
    while (now) {
        if (now.val === 0 && now.next) {
            resNow.next = new ListNode();
            resNow = resNow.next;
        } else if (now.val !== 0) {
            resNow.val += now.val;
        }
        now = now.next;
    }
    return newHead.next;
};

/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number[][]}
 */
var getAncestors = function(n, edges) {
    const parentMap = Array(n).fill(0).map(() => []);
    const ancestorMap = Array(n);
    for (var i = 0; i < edges.length; i++) {
        parentMap[edges[i][1]].push(edges[i][0]);
    }
    for (var i = 0; i < n; i++) {
        find(i, parentMap, ancestorMap);
    }
    return ancestorMap.map(item => item.sort((a, b) => a - b));
};

var find = function(i, parentMap, ancestorMap) {
    if (!ancestorMap[i]) {
        var res = [];
        var arr = parentMap[i];
        for (var j = 0; j < arr.length; j++) {
            res.push(arr[j], ...find(arr[j], parentMap, ancestorMap));
        }
        ancestorMap[i] = Array.from(new Set(res));
    }
    return ancestorMap[i];
};

/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {number[][]} descriptions
 * @return {TreeNode}
 */
var createBinaryTree = function(descriptions) {
    var nodeMap = {};
    var hasNoParentMap = {};
    for (var i = 0; i < descriptions.length; i++) {
        var [parent, child, isLeft] = descriptions[i];
        if (hasNoParentMap[parent] === undefined) hasNoParentMap[parent] = true;
        hasNoParentMap[child] = false;
        if (!nodeMap[parent]) nodeMap[parent] = new TreeNode(parent);
        if (!nodeMap[child]) nodeMap[child] = new TreeNode(child);
        if (isLeft) {
            nodeMap[parent].left = nodeMap[child];
        } else {
            nodeMap[parent].right = nodeMap[child];
        }
    }
    return nodeMap[Object.keys(hasNoParentMap).filter(key => hasNoParentMap[key])[0]];
};

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number[][]}
 */
var findDifference = function(nums1, nums2) {
    var map = {};
    for (var i = 0; i < nums1.length; i++) {
        map[nums1[i]] = (map[nums1[i]] || 0) | 1;
    }
    for (var i = 0; i < nums2.length; i++) {
        map[nums2[i]] = (map[nums2[i]] || 0) | 2;
    }
    var res = [new Set(), new Set()];
    for (var i = 0; i < nums1.length; i++) {
        if (!(map[nums1[i]] & 2)) {
            res[0].add(nums1[i]);
        }
    }
    for (var i = 0; i < nums2.length; i++) {
        if (!(map[nums2[i]] & 1)) {
            res[1].add(nums2[i]);
        }
    }
    return res.map(item => Array.from(item));
};

/**
 * @param {number[]} tasks
 * @return {number}
 */
var minimumRounds = function(tasks) {
    var map = {};
    for (var i = 0; i < tasks.length; i++) {
        if (!map[tasks[i]]) map[tasks[i]] = 0;
        map[tasks[i]]++;
    }
    var keys = Object.keys(map);
    var res = 0;
    for (var j = 0; j < keys.length; j++) {
        if (map[keys[j]] === 1) return -1;
        res += Math.ceil(map[keys[j]] / 3);
    }
    return res;
};

/**
 * @param {number[][]} flowers
 * @param {number[]} people
 * @return {number[]}
 */
var fullBloomFlowers = function(flowers, people) {
    var flowersSortByStart = flowers.map(flower => flower[0]).sort((a, b) => a - b);
    var flowersSortByEnd = flowers.map(flower => flower[1]).sort((a, b) => a - b);
    var peopleTimesSort = Array.from(people).sort((a, b) => a - b);
    var map = {};
    var startIndex = 0;
    var endIndex = 0;
    for (var i = 0; i < peopleTimesSort.length; i++) {
        var time = peopleTimesSort[i];
        // number of flowers started before or in time
        startIndex = findStartIndex(flowersSortByStart, time, startIndex);
        // number of flowers ended before time
        endIndex = findEndIndex(flowersSortByEnd, time, endIndex);
        // full bloom flower number = flower started number - flower ended number
        map[time] = startIndex - endIndex;
    }
    return people.map((time) => map[time]);
};

var findStartIndex = function(times, time, from) {
    for (var i = from; i <= times.length; i++) {
        if (times[i] <= time) continue;
        return i;
    }
};

var findEndIndex = function(times, time, from) {
    for (var i = from; i <= times.length; i++) {
        if (times[i] < time) continue;
        return i;
    }
};

/**
 * @param {string} num
 * @return {string}
 */
var largestGoodInteger = function(num) {
    var maxDigit = '';
    var digitLength = 0;
    for (var i = 0; i < num.length; i++) {
        if (num[i] === num[i - 1]) {
            digitLength += 1;
            if (digitLength >= 3 && num[i] > maxDigit) {
                maxDigit = num[i];
            }
        } else {
            digitLength = 1;
        }
    }
    return maxDigit.repeat(3);
};

/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @return {number}
 */
var averageOfSubtree = function(root) {
    return helper(root).res;
};

var helper = function(root) {
    if (!root) return { sum: 0, num: 0, res: 0 };
    var left = helper(root.left);
    var right = helper(root.right);
    var sum = left.sum + right.sum + root.val;
    var num = left.num + right.num + 1;
    var res = left.res + right.res + (Math.floor(sum / num) === root.val ? 1 : 0);
    return { sum, num, res };
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var totalSteps = function(nums) {
    var dp = Array(nums.length).fill(0);
    var stack = [];
    for (var i = nums.length - 1; i >= 0; i--) {
        while (stack.length && nums[i] > nums[stack[stack.length - 1]]) {
            dp[i] = Math.max(dp[i] + 1, dp[stack.pop()]);
        }
        stack.push(i);
    }
    return Math.max(...dp);
};

/**
 * @param {number[]} cookies
 * @param {number} k
 * @return {number}
 */
var distributeCookies = function(cookies, k) {
    var arr = Array(k).fill(0);
    return helper(cookies, k, 0, 0, arr);
};

var helper = function(cookies, k, i, n, map) {
    var min = Number.MAX_SAFE_INTEGER;
    if (i === cookies.length && n === k) return Math.max(...map);
    if (cookies.length - i < k - n) return min;
    for (var j = 0; j < k; j++) {
        map[j] += cookies[i];
