        max = Math.max(max, j - i + 1);
        j++;
    }
    return max;
};

/**
 * @param {number[]} cost
 * @param {number[]} time
 * @return {number}
 */
var paintWalls = function(cost, time) {
    var dp = Array(cost.length).fill(0).map(() => Array(cost.length + 1));
    return helper(cost, time, 0, cost.length, dp);
};

var helper = function(cost, time, i, remains, dp) {
    if (remains <= 0) return 0;
    if (i === cost.length) return Number.MAX_SAFE_INTEGER;
    if (dp[i][remains] !== undefined) return dp[i][remains];
    var paintByPaidPainter = cost[i] + helper(cost, time, i + 1, remains - time[i] - 1, dp);
    var paintByFreePainter = helper(cost, time, i + 1, remains, dp);
    dp[i][remains] = Math.min(paintByPaidPainter, paintByFreePainter);
    return dp[i][remains];
};

/**
 * @param {number[]} positions
 * @param {number[]} healths
 * @param {string} directions
 * @return {number[]}
 */
var survivedRobotsHealths = function(positions, healths, directions) {
    var res = [];
    var stack = [];
    var robots = positions.map((p, i) => [p, healths[i], directions[i], i]).sort((a, b) => a[0] - b[0]);
    for (var i = 0; i < robots.length; i++) {
        var robot = robots[i];
        if (robot[2] === 'R') {
            stack.push(robot);
            continue;
        }
        while (robot[1] > 0 && stack.length) {
            if (stack[stack.length - 1][1] < robot[1]) {
                stack.pop();
                robot[1] -= 1;
            } else if (stack[stack.length - 1][1] === robot[1]) {
                stack.pop();
                robot[1] = 0;
            } else {
                stack[stack.length - 1][1] -= 1;
                robot[1] = 0;
            }
        }
        if (robot[1] > 0) {
            res.push(robot);
        }
    }
    res.push(...stack);
    return res.sort((a, b) => a[3] - b[3]).map(a => a[1]);
};

/**
 * @param {number[]} nums
 * @param {number} target
 * @return {number}
 */
var maximumJumps = function(nums, target) {
    var dp = Array(nums.length);
    for (var i = nums.length - 1; i >= 0; i--) {
        dp[i] = i === nums.length - 1 ? 0 : -1;
        for (var j = i + 1; j < nums.length; j++) {
            if (Math.abs(nums[j] - nums[i]) <= target && dp[j] !== -1) {
                dp[i] = Math.max(dp[i], 1 + dp[j]);
            }
        }
    }
    return dp[0];
};

/**
 * @param {string} s
 * @return {string}
 */
var sortVowels = function(s) {
    var vowels = s.split('')
        .filter(isVowels)
        .sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0));
    var res = '';
    var index = 0;
    for (var i = 0; i < s.length; i++) {
        if (isVowels(s[i])) {
            res += vowels[index++];
        } else {
            res += s[i];
        }
    }
    return res;
};

var isVowels = function(char) {
    var chars = ['a', 'e', 'i', 'o', 'u'];
    return chars.includes(char.toLowerCase()) || chars.includes(char.toUpperCase());
};

/**
 * @param {number[]} usageLimits
 * @return {number}
 */
var maxIncreasingGroups = function(usageLimits) {
    var count = 0;
    var num = 0;
    var minCount = 1;
    usageLimits.sort((a, b) => a - b);
    for (var i = 0; i < usageLimits.length; i++) {
        count += usageLimits[i];
        if (count >= minCount) {
            num++;
            minCount += num + 1;
        }
    }
    return num;
};

/**
 * @param {string} num
 * @return {number}
 */
var minimumOperations = function(num) {
    var min = num.length;
    if (num.includes('0')) min = num.length - 1;
    var nums = ['25', '50', '75', '00'];
    for (var i = 0; i < nums.length; i++) {
        var m = 0;
        var count = 0;
        for (var j = num.length - 1; j >= 0; j--) {
            if (num[j] === nums[i][nums[i].length - 1 - m]) {
                m++;
                if (m === nums[i].length) {
                    min = Math.min(min, count);
                }
            } else {
                count++;
            }
        }
    }
    return min;
};

/**
 * @param {number} sx
 * @param {number} sy
 * @param {number} fx
 * @param {number} fy
 * @param {number} t
 * @return {boolean}
 */
var isReachableAtTime = function(sx, sy, fx, fy, t) {
    const x = Math.abs(sx - fx);
    const y = Math.abs(sy - fy);
    if (sx === fx && sy === fy && t === 1) {
        return false;
    }
    return Math.max(x, y) <= t;
};

/**
 * @param {string} s
 * @return {string}
 */
var maximumOddBinaryNumber = function(s) {
    var numOfOnes = s.split('').reduce((sum, num) => sum + Number(num), 0);
    return '1'.repeat(numOfOnes - 1) + '0'.repeat(s.length - numOfOnes) + '1';
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minOperations = function(nums) {
    var map = {};
    for (var i = 0; i < nums.length; i++) {
        var num = nums[i];
        map[num] = map[num] || 0;
        map[num] += 1;
    }
    var keys = Object.keys(map);
    var res = 0;
    for (var j = 0; j < keys.length; j++) {
        var num = keys[j];
        if (map[num] === 1) return -1;
        res += Math.ceil(map[num] / 3);
    }
    return res;
};

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[][]}
 */
var divideArray = function(nums, k) {
    nums.sort((a, b) => a - b);
    var res = [];
    for (var i = 0; i < nums.length; i += 3) {
        if (nums[i + 2] - nums[i] <= k) {
            res.push([nums[i], nums[i + 1], nums[i + 2]]);
        } else {
            return [];
        }
    }
    return res;
};

/**
 * @param {string} source
 * @param {string} target
 * @param {character[]} original
 * @param {character[]} changed
 * @param {number[]} cost
 * @return {number}
 */
var minimumCost = function(source, target, original, changed, cost) {
    var adjacentMap = {};
    for (var i = 0; i < cost.length; i++) {
        adjacentMap[original[i]] = adjacentMap[original[i]] || {};
        adjacentMap[original[i]][changed[i]] = Math.min(
            adjacentMap[original[i]][changed[i]] || Number.MAX_SAFE_INTEGER,
            cost[i],
        );
    }
    var res = 0;
    var minCostMap = {};
    for (var j = 0; j < source.length; j++) {
        minCostMap[source[j]] = minCostMap[source[j]] || dijkstra(source[j], adjacentMap);
        var costMap = minCostMap[source[j]];
        if (costMap[target[j]] === undefined) return -1;
        res += costMap[target[j]];
    }
    return res;
};

var dijkstra = function(s, adjacentMap) {
    var queue = new MinPriorityQueue();
    var minCostMap = {};
    queue.enqueue(s, 0);
    while (queue.size()) {
        var { element, priority } = queue.dequeue();
        if (minCostMap[element] <= priority) continue;
        minCostMap[element] = priority;
        var arr = Object.keys(adjacentMap[element] || {});
        for (var i = 0; i < arr.length; i++) {
            queue.enqueue(arr[i], priority + adjacentMap[element][arr[i]]);
        }
    }
    return minCostMap;
};

/**
 * @param {string} word
 * @return {number}
 */
var minimumPushes = function(word) {
    var frequencyMap = Array(26).fill(0);
    var a = 'a'.charCodeAt(0);
    for (var i = 0; i < word.length; i++) {
        frequencyMap[word[i].charCodeAt(0) - a] += 1;
    }
    var arr = frequencyMap.sort((a, b) => b - a);
    var res = 0;
    for (var i = 0; i < arr.length; i++) {
        res += Math.ceil((i + 1) / 8) * arr[i];
    }
    return res;
};

/**
 * @param {number[]} arr1
 * @param {number[]} arr2
 * @return {number}
 */
var longestCommonPrefix = function(arr1, arr2) {
    var trie = {};
    for (var i = 0; i < arr1.length; i++) {
        var str = `${arr1[i]}`;
        var map = trie;
        for (var j = 0; j < str.length; j++) {
            if (!map[str[j]]) {
                map[str[j]] = {};
            }
            map = map[str[j]];
        }
    }
    var max = 0;
    for (var i = 0; i < arr2.length; i++) {
        var str = `${arr2[i]}`;
        var map = trie;
        var len = 0;
        for (var j = 0; j < str.length; j++) {
            if (!map[str[j]]) {
                break;
            }
            len += 1;
            map = map[str[j]];
        }
        max = Math.max(max, len);
    }
    return max;
};
